#include <stdio.h>
#include <stddef.h>

int sum(const int *values, size_t count) {       /* read-only traversal. */
    int total = 0;
    for (size_t i = 0; i < count; i++) total += values[i];
    return total;
}

void scale(int *values, size_t count, int factor) {  /* in-place update. */
    for (size_t i = 0; i < count; i++) values[i] *= factor;
}

int main(void) {
    int temps[4] = {21, 19, 24, 22};             /* indexes 0..3. */
    size_t n = sizeof temps / sizeof temps[0];  /* 4: works HERE only. */
    printf("sum = %d\n", sum(temps, n));        /* 86. */
    scale(temps, n, 2);                         /* temps now 42, 38, 48, 44. */
    printf("first = %d\n", temps[0]);
    return 0;
}
```

